// ============================================================
// Constants
// ============================================================
const (
	DefaultHttpListen                  string = ":80"
	DefaultRenewalCheckIntervalSeconds int64  = 3600
)

// ============================================================
// Capacity Constants (for utilization monitoring)
// ============================================================
const (
	MaxSizeConfigFqdn             int = 32768
	MaxSizeConfigLetsEncryptEmail int = 32768
	MaxSizeConfigHttpListen       int = 32768
	MaxSizeGenesiscertdataFqdn    int = 32768
	MaxSizeCertmagicstateValue    int = 32768
	MaxSizeLockId                 int = 32768
)

// ============================================================
// TypeDefaults: Config
// ============================================================
// ConfigDefaults applies field-level default values to zero-valued fields.
func ConfigDefaults(v *Config) {
	if v.HttpListen == "" {
		v.HttpListen = DefaultHttpListen
	}
	if v.RenewalCheckIntervalSeconds == 0 {
		v.RenewalCheckIntervalSeconds = DefaultRenewalCheckIntervalSeconds
	}
}

// ============================================================
// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
	if dst.LetsEncryptEmail == "" {
		dst.LetsEncryptEmail = src.LetsEncryptEmail
	}
	if dst.HttpListen == "" {
		dst.HttpListen = src.HttpListen
	}
	if dst.RenewalCheckIntervalSeconds == 0 {
		dst.RenewalCheckIntervalSeconds = src.RenewalCheckIntervalSeconds
	}
}

// ============================================================
// Merge: GenesisState
// ============================================================
// MergeGenesisState fills zero-valued fields in dst from src.
func MergeGenesisState(dst, src *GenesisState) {
	if dst.CertData == nil {
		dst.CertData = src.CertData
	} else if src.CertData != nil {
		MergeGenesisCertData(dst.CertData, src.CertData)
	}
}

// ============================================================
// Merge: GenesisCertData
// ============================================================
// MergeGenesisCertData fills zero-valued fields in dst from src.
func MergeGenesisCertData(dst, src *GenesisCertData) {
	if dst.TlsCert == nil {
		dst.TlsCert = src.TlsCert
	}
	if dst.CertmagicState == nil {
		dst.CertmagicState = src.CertmagicState
	} else if src.CertmagicState != nil {
		MergeCertMagicState(dst.CertmagicState, src.CertmagicState)
	}
	if dst.LastRenewed == 0 {
		dst.LastRenewed = src.LastRenewed
	}
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
	if dst.Lock == nil {
		dst.Lock = src.Lock
	} else if src.Lock != nil {
		MergeLock(dst.Lock, src.Lock)
	}
}

// ============================================================
// Merge: CertMagicState
// ============================================================
// MergeCertMagicState fills zero-valued fields in dst from src.
func MergeCertMagicState(dst, src *CertMagicState) {
	if !dst.IsDir {
		dst.IsDir = src.IsDir
	}
	if len(dst.Value) == 0 {
		dst.Value = src.Value
	}
	if dst.ModTime == 0 {
		dst.ModTime = src.ModTime
	}
}

// ============================================================
// Merge: Lock
// ============================================================
// MergeLock fills zero-valued fields in dst from src.
func MergeLock(dst, src *Lock) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.Counter == 0 {
		dst.Counter = src.Counter
	}
}
